ActorFrame.OnCommand:
%function(self)

	songName = GAMESTATE:GetCurrentSong():GetSongDir();

	for i=0, 3 do
	_G['receptor_rotationx_'..i] = 0;
	_G['receptor_rotationy_'..i] = 0;
	_G['receptor_rotationz_'..i] = 0;
	_G['receptor_x_'..i] = 0;
	_G['receptor_y_'..i] = 0;
	_G['receptor_z_'..i] = 0;
	_G['receptor_zoom_'..i] = 1;
	_G['receptor_zoomx_'..i] = 1;
	_G['receptor_zoomy_'..i] = 1;
	_G['receptor_zoomtowidth_'..i] = nil;
	_G['receptor_zoomtoheight_'..i] = nil;
	_G['receptor_tint_'..i] = nil;
	_G['receptor_fade_'..i] = nil;
	_G['receptor_effect_'..i] = 'pulse';
	_G['receptor_effectset_'..i] = false;
	_G['receptor_effectcontrol_'..i] = {1,1,0,0,'bgm'};
	-------
	_G['noteskin_rotationx_'..i] = 0;
	_G['noteskin_rotationy_'..i] = 0;
	_G['noteskin_rotationz_'..i] = 0;
	_G['noteskin_x_'..i] = 0;
	_G['noteskin_y_'..i] = 0;
	_G['noteskin_z_'..i] = 0;
	_G['noteskin_zoom_'..i] = 1;
	_G['noteskin_zoomx_'..i] = 1;
	_G['noteskin_zoomy_'..i] = 1;
	_G['noteskin_zoomtowidth_'..i] = nil;
	_G['noteskin_zoomtoheight_'..i] = nil;
	_G['noteskin_tint_'..i] = nil;
	_G['noteskin_fade_'..i] = nil;
	_G['noteskin_effect_'..i] = 'pulse';
	_G['noteskin_effectset_'..i] = false;
	_G['noteskin_effectcontrol_'..i] = {1,1,0,0,'bgm'};
	end

end
